// CPR/First Aid Practice Test 2. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering different situations from Practice Test 1.
import {q, mix} from './q.js';
const AHA_BLS='AHA Basic Life Support', AHA_FA='AHA Heartsaver First Aid', ARC_BLS='ARC Basic Life Support', ARC_FA='ARC First Aid/CPR/AED', DHO='Simmers, DHO: Health Science';
const GEN='General Concepts', CPR='BLS/CPR for Adults, Children and Infants', AED='AED for Adults, Children and Infants', ADV='CPR with Advanced Airway', RB='Mouth-to-Mouth/Rescue Breathing', CH='Relief of Choking';
const BASIC='Basic', MED='Medical Emergencies', INJ='Injury Emergencies', ENV='Environmental Emergencies';

export default {
 id:'cpr-first-aid-2',
 event:'CPR/First Aid',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'AHA and American Red Cross BLS and First Aid, and DHO: Health Science',
 plan:[
  {area:'Basic Life Support',weight:40,topics:[GEN,CPR,AED,ADV,RB,CH]},
  {area:'First Aid',weight:60,topics:[BASIC,MED,INJ,ENV]}
 ],
 questions:mix([
  q(GEN,'In the AHA adult out-of-hospital Chain of Survival, which link comes immediately after recognizing cardiac arrest and activating the emergency response system?','High-quality CPR',['Rapid defibrillation','Advanced resuscitation','Post–cardiac arrest care'],'B','The out-of-hospital chain is activation, high-quality CPR, rapid defibrillation, advanced resuscitation, post–cardiac arrest care and recovery.',AHA_BLS),
  q(GEN,'A rescuer checks an unresponsive adult for breathing and a pulse. What is the maximum time this check should take?','10 seconds',['5 seconds','15 seconds','30 seconds'],'D','Check breathing and pulse at the same time for at least 5 but no more than 10 seconds so compressions are not delayed.',AHA_BLS),
  q(GEN,'An unresponsive adult makes occasional snoring gasps about every 10 seconds. How should these breaths be treated?','As agonal gasps, a sign of cardiac arrest',['As normal breathing that needs only monitoring','As a sign the airway is fully open','As a reason to delay CPR for 2 minutes'],'A','Agonal gasps are not effective breathing. A person who is unresponsive and only gasping needs CPR.',AHA_BLS),
  q(GEN,'During a two-rescuer adult resuscitation, how often should rescuers switch the compressor role?','About every 2 minutes',['Every 30 seconds','Every 5 minutes','Only when the compressor asks'],'C','Compressor fatigue lowers quality within minutes. Switch about every 2 minutes (5 cycles of 30:2), ideally in less than 5 seconds.',AHA_BLS),
  q(CPR,'What compression rate is recommended for adults, children and infants?','100–120 per minute',['80–100 per minute','120–140 per minute','At least 140 per minute'],'B','Rates above 120 per minute reduce depth and recoil; rates below 100 reduce blood flow.',AHA_BLS),
  q(CPR,'What compression depth is recommended for an adult?','At least 2 in but not more than 2.4 in',['About 1.5 in','At least 3 in','One-half the depth of the chest'],'D','Compressing deeper than 2.4 inches (6 cm) increases the risk of injury without added benefit.',AHA_BLS),
  q(CPR,'Why must rescuers allow full chest recoil after each compression?','It lets the heart refill with blood',['It lets the lungs exhale fully','It prevents rib fractures entirely','It allows the AED to analyze'],'A','Leaning on the chest raises pressure inside it and reduces blood return to the heart and coronary perfusion.',AHA_BLS),
  q(CPR,'A lone rescuer witnesses a 6-year-old suddenly collapse and has a phone. What should the rescuer do?','Call 911 and get an AED, then begin CPR',['Give 2 minutes of CPR before calling','Give 5 rescue breaths before calling','Wait for another rescuer to arrive'],'C','A sudden, witnessed collapse is likely cardiac, so early defibrillation is the priority. For an unwitnessed child arrest, give 2 minutes of CPR first.',AHA_BLS),
  q(CPR,'Which compression-to-ventilation ratio should a single rescuer use for an infant?','30:2',['15:2','5:1','3:1'],'B','A single rescuer uses 30:2 for all ages; two rescuers use 15:2 for infants and children.',AHA_BLS),
  q(CPR,'An infant’s pulse is 50 per minute with signs of poor perfusion despite adequate breathing support. What should be done?','Begin chest compressions',['Continue rescue breaths only','Wait 2 minutes and recheck','Give abdominal thrusts'],'D','A heart rate below 60 per minute with poor perfusion in an infant or child calls for CPR.',AHA_BLS),
  q(AED,'Where should AED pads be placed on an adult using the standard position?','Right upper chest and left side below the armpit',['Both pads on the center of the chest','Left upper chest and right lower back','Both pads on the back between the shoulders'],'A','Anterolateral placement puts the heart between the pads so current flows through it.',ARC_BLS),
  q(AED,'Where should AED pads be placed on an infant when they would touch on the front of the chest?','Center of the chest and center of the back',['Both pads on the right side','One pad on each upper arm','Both pads side by side on the abdomen'],'C','Anterior-posterior placement keeps the pads from touching, which would let the current arc across the skin.',ARC_BLS),
  q(AED,'An adult in cardiac arrest has a bulge under the skin of the upper left chest from an implanted pacemaker. How should the pads be placed?','At least 1 in away from the device',['Directly over the device','Only after the device is removed','On the arms instead of the chest'],'B','Placing a pad over an implanted device can block current and damage it; move the pad aside or use front-to-back placement.',ARC_BLS),
  q(AED,'Why should everyone stay clear of the patient while the AED analyzes the rhythm?','Movement can disrupt the analysis',['The AED is charging the patient','Touching the patient lowers the voltage','The pads are hot during analysis'],'D','Motion and contact can produce artifact. Everyone must also be clear during a shock for their own safety.',ARC_BLS),
  q(ADV,'Once an advanced airway is in place during adult CPR, how should breaths be given?','1 breath every 6 s, no pauses',['2 breaths after every 30 compressions','1 breath every 2 seconds','10 breaths every minute with pauses'],'A','With an advanced airway, compressions continue without pauses and breaths are given at 10 per minute.',AHA_BLS),
  q(ADV,'Which device provides objective confirmation that an advanced airway is placed in the trachea?','Waveform capnography',['A pulse oximeter','A blood pressure cuff','A manual pupil check'],'C','A sustained ETCO₂ waveform confirms placement and also reflects the quality of CPR.',AHA_BLS),
  q(RB,'An adult has a strong pulse but is not breathing normally. How often should rescue breaths be given?','1 breath every 6 seconds',['1 breath every 2–3 seconds','2 breaths every 30 seconds','1 breath every 15 seconds'],'B','Recheck the pulse about every 2 minutes. Children and infants receive 1 breath every 2–3 seconds.',AHA_BLS),
  q(RB,'Each rescue breath should last about how long and produce what result?','About 1 second, with visible chest rise',['About 3 seconds, with a full abdomen','About 5 seconds, until resistance is felt','As long as possible, with no chest rise'],'D','Forceful or long breaths can fill the stomach with air, causing vomiting and aspiration.',AHA_BLS),
  q(CH,'A choking adult becomes unresponsive. After calling 911, what should the rescuer do?','Begin CPR, looking in the mouth before breaths',['Continue abdominal thrusts on the floor','Perform blind finger sweeps first','Wait for EMS to remove the object'],'A','Compressions may dislodge the object. Remove it only if seen; blind finger sweeps can push it deeper.',ARC_BLS),
  q(CH,'Which finding indicates a severe airway obstruction in a conscious adult?','Inability to speak or cough forcefully',['Loud, forceful coughing','Clear speech with a hoarse voice','Gagging followed by normal breathing'],'C','A person who can cough forcefully should be encouraged to keep coughing; a silent or weak cough needs abdominal thrusts.',ARC_BLS),
  q(BASIC,'Before touching an injured person, what is the first thing a first aider should do?','Make sure the scene is safe',['Check for a pulse','Ask for the person’s name','Start rescue breaths'],'B','A first aider who becomes injured cannot help and adds another victim.',AHA_FA),
  q(BASIC,'An unresponsive adult is lying in the road with no family present. Why can a first aider still give care?','Consent is implied for unresponsive people',['Care never requires any consent','Only police can give consent','Family consent can be obtained later'],'D','Implied consent assumes a reasonable person would want help when unable to answer.',AHA_FA),
  q(BASIC,'What do Good Samaritan laws generally do?','Protect good-faith rescuers',['Require everyone to give first aid','Protect people who give care for payment','Allow first aiders to perform surgery'],'A','Protection usually requires acting in good faith, within one’s training and without gross negligence.',DHO),
  q(BASIC,'In the SAMPLE history, what does the “L” stand for?','Last oral intake',['Level of consciousness','Location of pain','Length of illness'],'C','SAMPLE is Signs and symptoms, Allergies, Medications, Past history, Last oral intake and Events leading up.',ARC_FA),
  q(BASIC,'A first aider finds a person whose skin is pale, cool and clammy, with a fast, weak pulse after an injury. What is the most likely condition?','Shock',['Heat stroke','Hyperglycemia','Simple fainting'],'B','Keep the person lying flat, maintain body temperature and call 911.',AHA_FA),
  q(BASIC,'Which is the best way to protect yourself from blood when no gloves are available?','Use a plastic bag or barrier over your hands',['Use bare hands and wash later','Wrap your hands in the victim’s clothes','Avoid helping until EMS arrives'],'D','Improvised barriers help, and hands should still be washed with soap and water afterward.',DHO),
  q(BASIC,'Using the AVPU scale, how is a person who answers questions but is confused about the date classified?','Alert',['Voice','Pain','Unresponsive'],'A','Alert means eyes are open and the person responds spontaneously, even if disoriented; note the confusion separately.',ARC_FA),
  q(MED,'Using the BE FAST signs, which finding most suggests a stroke?','Sudden facial droop on one side',['Gradual tiredness over weeks','Chest pain after a heavy meal','Numbness in both hands after sitting'],'C','BE FAST is Balance, Eyes, Face, Arms, Speech and Time to call 911. Note when symptoms began.',AHA_FA),
  q(MED,'A person with diabetes is sweaty, shaky and confused but can swallow. What should the first aider give?','About 15–20 g of glucose',['A dose of insulin','Nothing by mouth at all','A large glass of water only'],'B','Glucose tablets or a sugary drink treat low blood sugar. Call 911 if the person cannot swallow or does not improve.',AHA_FA),
  q(MED,'During a seizure, which action is correct?','Protect the head and time the seizure',['Hold the arms and legs down firmly','Place a spoon between the teeth','Give water as soon as it starts'],'D','After jerking stops, roll the person onto their side. Call 911 for seizures over 5 minutes or first-time seizures.',AHA_FA),
  q(MED,'A person with asthma is wheezing and struggling to speak. What should a first aider do first?','Help them use their quick-relief inhaler',['Have them lie flat on their back','Give an antihistamine pill','Start chest compressions'],'A','A quick-relief (rescue) inhaler opens the airways. Call 911 if breathing does not improve or worsens.',ARC_FA),
  q(MED,'A man has crushing chest pain spreading to his left arm and jaw. Which action is appropriate if he is not allergic?','Call 911 and have him chew 162–325 mg aspirin',['Have him walk to the car for a ride','Give him a nitroglycerin tablet from a friend','Have him drink cold water and rest'],'C','Do not give someone else’s nitroglycerin. Keep the person at rest and get an AED ready.',AHA_FA),
  q(MED,'A woman feels faint after standing quickly but has not lost consciousness. What should she do?','Lie down or sit with her head lowered',['Stand still with her knees locked','Walk briskly around the room','Hold her breath for 10 seconds'],'B','Lying flat restores blood flow to the brain. Fainting with chest pain or no warning needs medical evaluation.',ARC_FA),
  q(MED,'A child swallowed an unknown amount of a household cleaner and is alert. What is the first step?','Call Poison Control at 1-800-222-1222',['Induce vomiting with a finger','Give milk until the child vomits','Wait to see if symptoms appear'],'D','Do not induce vomiting unless told to. Call 911 if the child is unresponsive, seizing or having trouble breathing.',AHA_FA),
  q(MED,'Hives, swelling of the lips and trouble breathing begin minutes after a bee sting. What is the most important treatment?','Epinephrine auto-injector into the outer thigh',['An oral antihistamine taken alone','A cold pack on the sting site','Scraping the stinger out with a card'],'A','Epinephrine is the first-line treatment for anaphylaxis; antihistamines are not enough. Call 911.',AHA_FA),
  q(MED,'Which symptom pattern more commonly signals a heart attack in women, older adults and people with diabetes?','Shortness of breath, nausea or back pain',['Sharp pain only in the fingertips','Sudden high fever with a rash','Loss of hearing in one ear'],'C','These groups more often have atypical signs, which delays care. Treat suspected heart attack the same way.',AHA_FA),
  q(MED,'After naloxone is given, an overdose victim begins breathing. Why must the first aider stay with the person?','Naloxone may wear off before the opioid',['Naloxone causes immediate heart failure','The person will need a second CPR cycle','Naloxone permanently blocks breathing'],'B','Overdose can return as naloxone wears off. Place the person in the recovery position and wait for EMS.',AHA_FA),
  q(INJ,'Which is the first and most effective step to control external bleeding from an arm wound?','Firm, direct pressure on the wound',['Elevating the arm above the heart','Pressing on a pressure point','Applying an ice pack'],'D','Direct pressure with a dressing controls most bleeding. Use a tourniquet for life-threatening limb bleeding that pressure does not stop.',AHA_FA),
  q(INJ,'A nosebleed is best treated by:','Leaning forward and pinching the soft nose',['Tilting the head back','Lying flat on the back','Packing the nose with tissue only'],'A','Leaning forward keeps blood from running down the throat. Pinch for at least 10–15 minutes.',AHA_FA),
  q(INJ,'A person has a painful, deformed forearm after a fall. What should the first aider do?','Splint it in the position found',['Straighten it before splinting','Massage it to reduce swelling','Have the person move it to test it'],'C','Immobilize the joints above and below the injury, and check circulation beyond it before and after splinting.',ARC_FA),
  q(INJ,'Which care is recommended for a superficial (first-degree) burn?','Cool running water, 10+ minutes',['Butter or oil to soothe it','Ice applied directly to the skin','Popping any blisters right away'],'B','Cool water stops the burning process. Ice can damage tissue, and butter traps heat and raises infection risk.',AHA_FA),
  q(INJ,'A worker splashes a strong chemical into one eye. What should be done?','Flush with water for 15+ minutes',['Rub the eye to remove the chemical','Cover the eye tightly and wait','Neutralize it with vinegar'],'D','Flush away from the uninjured eye, remove contact lenses if possible and call 911 or Poison Control.',AHA_FA),
  q(INJ,'A long splinter of wood is stuck deep in a person’s thigh. How should it be handled?','Stabilize it in place with bulky dressings',['Pull it out quickly to stop bleeding','Push it farther in to stop bleeding','Cut it flush with the skin'],'A','Removing an impaled object can cause severe bleeding. Leave it for medical personnel.',ARC_FA),
  q(INJ,'Using RICE for a sprained ankle, how long should ice usually be applied at a time?','About 20 minutes',['About 2 minutes','About 60 minutes','Until the skin is numb all day'],'C','Place a cloth between ice and skin. Rest, ice, compression and elevation reduce pain and swelling.',ARC_FA),
  q(INJ,'A person is drowsy, vomiting and confused hours after a hard blow to the head. What should the first aider do?','Call 911 for possible brain injury',['Let the person sleep it off at home','Give pain medicine and leave','Have the person walk it off'],'B','Worsening symptoms after a head injury may mean bleeding in the skull, which is an emergency.',AHA_FA),
  q(INJ,'A fingertip is cut off in an accident. How should the amputated part be cared for?','Wrap, bag and keep it cool on ice',['Place it directly in a cup of ice','Put it in a glass of tap water','Wash it with alcohol and keep it dry'],'D','Direct contact with ice causes frostbite damage. Send the part with the person to the hospital.',AHA_FA),
  q(ENV,'Which findings suggest heat exhaustion rather than heat stroke?','Heavy sweating and normal mental status',['Confusion and seizures','Hot skin and unresponsiveness','Temperature above 104 °F with confusion'],'A','Move the person to a cool place and give fluids. Changes in mental status suggest heat stroke, which is an emergency.',AHA_FA),
  q(ENV,'Which is the recommended way to rewarm a frostbitten hand when there is no risk of refreezing?','Warm water at about 99–104 °F',['Rubbing it with snow','Holding it near an open flame','Massaging it vigorously'],'C','Rubbing and direct heat damage frozen tissue. Do not rewarm if it might refreeze.',ARC_FA),
  q(ENV,'A person bitten by a pit viper should receive which care?','Keep them still and get to a hospital',['Cut the bite and suck out venom','Apply a tight tourniquet','Apply ice directly to the bite'],'B','Remove rings and tight items, keep the person calm and still and get emergency care for antivenom.',AHA_FA),
  q(ENV,'What is the recommended way to remove a tick?','Pull it straight out with tweezers',['Burn it with a match until it backs out','Smother it with petroleum jelly','Twist it off quickly with fingers'],'D','Clean the area afterward and watch for rash or fever, which can signal tick-borne disease.',AHA_FA)
 ],211)
};
